// ============================================================
// LINUX PASSWORD AGE AUDIT
// Users: root + premd
// ============================================================

const items = $input.all();

const results = [];

const PASSWORD_AGE_WARNING_DAYS = 90;


// ============================================================
// Parse Linux date
// ============================================================

function parseDate(value) {

    if (!value) {
        return null;
    }

    value = value.trim();

    if (
        value.toLowerCase() === 'never' ||
        value.toLowerCase() === 'none'
    ) {
        return null;
    }

    const date = new Date(value);

    if (isNaN(date.getTime())) {
        return null;
    }

    return date;
}


// ============================================================
// Calculate password age
// ============================================================

function calculateAge(date) {

    if (!date) {
        return null;
    }

    const now = new Date();

    return Math.floor(
        (now.getTime() - date.getTime()) /
        (1000 * 60 * 60 * 24)
    );
}


// ============================================================
// Process every Ansible item
// ============================================================

for (const item of items) {

    const stdout = String(item.json.stdout || '');
    const stderr = String(item.json.stderr || '');

    if (!stdout.trim()) {
        continue;
    }

    const lines = stdout.split(/\r?\n/);

    let hostname = '';
    let currentUser = '';
    let userData = {};


    // ========================================================
    // Save one user
    // ========================================================

    function saveUser() {

        if (!hostname || !currentUser) {
            return;
        }

        const lastPasswordChange =
            parseDate(userData.lastPasswordChange);

        const passwordExpires =
            parseDate(userData.passwordExpires);

        const passwordAgeDays =
            calculateAge(lastPasswordChange);

        const today = new Date();

        let status = 'UNKNOWN';


        // ----------------------------------------------------
        // Password expired
        // ----------------------------------------------------

        if (
            passwordExpires &&
            passwordExpires < today
        ) {

            status = 'EXPIRED';

        }


        // ----------------------------------------------------
        // Password age >= 90 days
        // ----------------------------------------------------

        else if (
            passwordAgeDays !== null &&
            passwordAgeDays >= PASSWORD_AGE_WARNING_DAYS
        ) {

            status = 'WARNING';

        }


        // ----------------------------------------------------
        // Password healthy
        // ----------------------------------------------------

        else if (
            passwordAgeDays !== null
        ) {

            status = 'HEALTHY';
        }


        // ----------------------------------------------------
        // Output
        // ----------------------------------------------------

        results.push({

            json: {

                hostname: hostname,

                username: currentUser,

                last_password_change:
                    userData.lastPasswordChange || 'unknown',

                password_age_days:
                    passwordAgeDays,

                password_expires:
                    userData.passwordExpires || 'never',

                password_inactive:
                    userData.passwordInactive || 'never',

                account_expires:
                    userData.accountExpires || 'never',

                minimum_days:
                    userData.minimumDays || '',

                maximum_days:
                    userData.maximumDays || '',

                warning_days:
                    userData.warningDays || '',

                threshold_days:
                    PASSWORD_AGE_WARNING_DAYS,

                status: status
            }
        });
    }


    // ========================================================
    // Read Ansible output
    // ========================================================

    for (const rawLine of lines) {

        const line = rawLine.trim();

        if (!line) {
            continue;
        }


        // ----------------------------------------------------
        // HOST
        // ----------------------------------------------------

        if (line.startsWith('HOST|')) {

            hostname =
                line.substring(5).trim();

            continue;
        }


        // ----------------------------------------------------
        // USER
        // ----------------------------------------------------

        if (line.startsWith('USER|')) {

            // Save previous user
            saveUser();

            currentUser =
                line.substring(5).trim();

            userData = {};

            continue;
        }


        // ----------------------------------------------------
        // Ignore Ansible headers
        // ----------------------------------------------------

        if (
            line.startsWith('=====') ||
            line.includes('SUCCESS | rc=0') ||
            line.includes('CHANGED | rc=0')
        ) {
            continue;
        }


        // ----------------------------------------------------
        // Parse chage output
        //
        // Example:
        //
        // Last password change : Jun 20, 2026
        // Password expires     : Sep 18, 2026
        // ----------------------------------------------------

        if (line.includes(':')) {

            const parts = line.split(':');

            if (parts.length < 2) {
                continue;
            }

            const key =
                parts[0].trim();

            const value =
                parts.slice(1)
                    .join(':')
                    .trim();


            switch (key) {

                case 'Last password change':

                    userData.lastPasswordChange =
                        value;

                    break;


                case 'Password expires':

                    userData.passwordExpires =
                        value;

                    break;


                case 'Password inactive':

                    userData.passwordInactive =
                        value;

                    break;


                case 'Account expires':

                    userData.accountExpires =
                        value;

                    break;


                case 'Minimum number of days between password change':

                    userData.minimumDays =
                        value;

                    break;


                case 'Maximum number of days between password change':

                    userData.maximumDays =
                        value;

                    break;


                case 'Number of days of warning before password expires':

                    userData.warningDays =
                        value;

                    break;
            }
        }
    }


    // ========================================================
    // Save last user
    // ========================================================

    saveUser();
}


// ============================================================
// If nothing was parsed, return diagnostic information
// ============================================================

if (results.length === 0) {

    return [

        {

            json: {

                status: 'NO_DATA_PARSED',

                message:
                    'No password audit records were parsed from Ansible output.',

                input_items:
                    items.length,

                hint:
                    'Check the Ansible node stdout for HOST| and USER| lines.'
            }

        }

    ];
}


// ============================================================
// Return results
// ============================================================

return results;
